pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(this));
        // set a non-zero, non-test-contract owner
        vm.prank(address(1)); // initial owner is address(0) - need to set first
        c.transferOwnership(newOwner);

        address ownerBefore = c.owner();

        // call owned() as the current owner
        vm.prank(newOwner);
        c.owned();

        address ownerAfter = c.owner();

        // The rule: after calling owned(), the owner should NOT revert to the original owner (address(0))
        assertTrue(ownerAfter == newOwner || ownerAfter != address(0));
    }
}

