pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // Get the original owner
        address originalOwner = c.owner();
        // Call owned() which requires onlyOwner
        // To make the caller the owner, we need to set the owner first
        // But since we don't have a setter, we just call owned() after ensuring msg.sender is owner
        // Actually the onlyOwner modifier requires msg.sender == owner, and owner is initially address(0)
        // So we need to set owner first via transferOwnership, but the mutant's transferOwnership does nothing
        // So we'll use vm.prank to impersonate the current owner (initially address(0))
        vm.prank(originalOwner);
        c.owned();
        // Now the owner should still be the same
        assertTrue(c.owner() == originalOwner);
    }
}

