pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        address ownerBefore = c.owner();
        vm.prank(caller);
        // Wrap in try/catch to handle reverts (only owner can call owned())
        try c.owned() {} catch {}
        address ownerAfter = c.owner();
        assertTrue(ownerBefore == ownerAfter);
    }
}

