pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0) && newOwner != address(this));

        // Set the owner to this contract for the test
        c.transferOwnership(address(this));

        // Now call owned() as the owner, which should allow transferOwnership
        // But we first need to set the owner to the test contract
        // Actually, let's directly test the invariant:
        // After calling transferOwnership, the owner should be the newOwner
        c.transferOwnership(address(this)); // Set owner to this contract
        address ownerBefore = c.owner();

        // Now call transferOwnership with the fuzzed address
        c.transferOwnership(newOwner);
        address ownerAfter = c.owner();

        assertTrue(ownerAfter == newOwner);
    }
}

